// DELETE /api/schedules/[id] — remove a report schedule.
//
//   200 → { ok: true }, 404 unknown schedule, 400 invalid id
//   (PDFs already generated by the schedule stay in the reports list.)

import { NextResponse } from 'next/server';
import { toErrorResponse } from '@/server/http';
import { deleteReportSchedule } from '@/server/reportscheduling';
import { governanceIdSchema } from '@/server/validation';
import { requireRole, requireUser } from '@/server/authz';

export const dynamic = 'force-dynamic';

export async function DELETE(req: Request, context: { params: Promise<{ id: string }> }) {
  try {
    await requireRole(req, 'engineer'); // phase-2 authz: ops mutation
    const { id } = await context.params;
    const scheduleId = governanceIdSchema.parse(id);
    await deleteReportSchedule(scheduleId);
    return NextResponse.json({ ok: true });
  } catch (err) {
    return toErrorResponse(err);
  }
}
